-- ---------------------------------------------------------------------------
-- S. 5653 (119th) — Bipartisan American Affordability and Jobs Act of 2026 (BAAJA)
-- ---------------------------------------------------------------------------
-- Generated by scripts/gen-baaja-migration.mjs from db/bill-standard/119-s-5653.json.
-- Do not hand-edit: once applied, roll forward with a new migration.
--
-- 1 measure · 18 issue mappings · 6 roll calls · 600 member votes · 4 sponsor rows · 12 timeline rows
--
-- WHY THIS EXISTS
-- BAAJA had a bill page built from its ground-truth ledger but no Voting Record row,
-- so the bill panel resolved nothing and printed "Could not load this bill right now."
-- This adds the row and everything the panel reads, copied from the ledger.
--
-- ONE MAPPING ROW PER DIRECTION
-- The ledger records 18 rows over 15 keys: tribal_consultation, property_rights and
-- mine_cleanup each have a yea_supports row and a yea_opposes row, citing different
-- sections (the ledger's split-mapping rule). The unique index on vr_measure_issues
-- was (measure_id, issue_key), which cannot hold that. It is widened here, for every
-- measure, to (measure_id, issue_key, support_meaning). No existing row moves: every
-- pair the old index allowed is still unique under the new one.
--
-- THE ROLL CALLS ARE THE VEHICLE'S
-- S. 5653 has had no vote of its own. Its text is moving as S.Amdt. 6883, a full
-- substitute to H.R. 2347. The six Senate roll calls on that text are attached to this
-- measure, each with its real question, so the question names the vehicle. Roll 267
-- (S.Amdt. 6883 agreed to, 69-27) is the one vote on the BAAJA text itself; the other
-- five are cloture, motion-to-proceed and budget-waiver votes, typed as such so they
-- carry procedural weight downstream. All 100 senators on each roll are roster-linked.
-- The ledger gives each vote's date but not its time, so each is stamped at noon
-- Eastern on that date.
--
-- Idempotent: the measure is created only when absent; every other insert is
-- ON CONFLICT DO NOTHING.
-- ---------------------------------------------------------------------------

DROP INDEX IF EXISTS vr_measure_issues_unique;
CREATE UNIQUE INDEX IF NOT EXISTS vr_measure_issues_unique
  ON vr_measure_issues (measure_id, issue_key, support_meaning);

DO $$
DECLARE
  m_s5653 integer;
  rc integer;
BEGIN

  -- ── measure ───────────────────────────────────────────────────────────────
  SELECT id INTO m_s5653 FROM vr_measures
   WHERE congress = 119 AND chamber = 'senate' AND number = 'S. 5653' LIMIT 1;
  IF m_s5653 IS NULL THEN
    VALUES ('bill', 119, 'senate', 'S. 5653', 'Bipartisan American Affordability and Jobs Act of 2026', 'Bipartisan American Affordability and Jobs Act of 2026',
      'This bill changes how the federal government reviews and approves energy, mining and other building projects. It sets deadlines for environmental reviews, gives people 150 days to sue over a permit, and limits when agencies can cancel a permit already granted. It narrows parts of the Clean Water Act, Endangered Species Act and historic-preservation reviews, including how Tribes take part. It makes large data centers pay the grid costs they cause instead of other customers. The Congressional Budget Office’s preliminary estimate says the Senate version would add less than $1 billion to deficits over 2027-2036. S. 5653 is in committee; its text is moving as a Senate amendment to H.R. 2347, adopted 69-27 on November 18, 2026.',
      DATE '2026-09-30', 'capito', 'pending', 'https://www.congress.gov/bill/119th-congress/senate-bill/5653', 'Congress.gov',
      '{"congressGovId":"s5653-119","congressGovUrl":"https://www.congress.gov/bill/119th-congress/senate-bill/5653","billStatusUrl":"https://www.govinfo.gov/bulkdata/BILLSTATUS/119/s/BILLSTATUS-119s5653.xml","policyArea":"Environmental Protection","officialTitle":"A bill to prescribe permitting reform, and for other purposes.","sponsorName":"Sen. Capito, Shelley Moore [R-WV]","acronym":"BAAJA","floorVehicle":"H.R. 2347","floorVehicleAmendment":"S.Amdt. 6883","groundTruthLedger":"db/bill-standard/119-s-5653.json"}'::jsonb)
    RETURNING id INTO m_s5653;
  END IF;

  -- ── issue mappings: the ledger's 18 rows, in ledger order, verbatim ───────
  -- No weight, rank or primary flag: the ledger carries none (every row 100, none primary).
      'The key''s scope is "how long a federal review of a project takes and who may challenge it". The bill sets 2-year and 1-year NEPA deadlines (1106), a 150-day window to sue (1110, 1205, 1305, 2201, and 1134 in the substitute), narrows what triggers review (1102, 2301), and shortens ESA consultation (1302). Advanced = narrower review and firm deadlines.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'datacenter_power', 100, false, 'yea_supports',
      'Chip: "Make data centers ... pay their own way, so they don''t raise family utility bills." Sec. 2107 assigns transmission costs fully to data-center owners and operators, and bars recovering their incremental costs from other customers.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'energy_production', 100, false, 'yea_supports',
      'Scope includes supply and "firm generating capacity". The bill drops federal drilling permits on mostly non-federal units (2211), keeps issued permits in place (1401), opens markets to dispatchable behind-the-meter resources (2108), eases hydropower licensing, and in the substitute eases nuclear licensing (1501-1503).',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'lands_energy', 100, false, 'yea_supports',
      'Scope names "hardrock mining and the ground a claimant may occupy to work a claim" and leasing availability on federal acreage. Sec. 2215 lets a claimant locate as many mill sites as reasonably necessary; Sec. 2223 moves geothermal lease sales from every 2 years to every year.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'lands_preserve', 100, false, 'yea_opposes',
      'Scope files endangered-species and protected-area measures here. Operative changes cut against protection: shorter ESA consultation (1302) and new authority to grant offshore rights-of-way inside sanctuaries and monuments (2251). On the other side are authorizations of appropriations ($150M a year for ESA, $50M a year for a coastal fund) and wildlife-plan deadlines; authorizations spend nothing until appropriated. Read as yea_opposes with that counterweight stated. Contested: see claims.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'states_federal_power', 100, false, 'yea_opposes',
      'Chip: "let the state''s choice stand." Sec. 1202 limits what a State may weigh or condition in a section 401 certification, and Sec. 2101 widens FERC''s power to permit interstate lines over State siting. Both make the federal rule govern. The State roles in Secs. 1105(a)(5), 1304 and 1306 are delegations of federal work, not preemption, so they do not reverse this.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'judicial_check', 100, false, 'yea_opposes',
      'Scope: "the reach of a court''s order against the executive branch ... equitable relief." Sec. 1110(5) makes remand "without vacatur or issuance of an injunction" the only remedy for a NEPA violation, with a narrow preliminary-injunction exception. Chip: "Let federal courts halt unlawful executive action."',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'infrastructure', 100, false, 'yea_supports',
      'Chip names "the power grid." Title I widens FERC transmission siting (2101), speeds reconductoring, and requires regional and interregional planning. The mechanism is siting and planning authority, not new federal money.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'cost_living', 100, false, 'yea_supports',
      'Chip names utility prices. Sec. 2107 keeps data-center grid costs off other customers'' rates. Supporters'' household-savings figures are modeling, not text, and are not relied on here.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'enviro_balance', 100, false, 'yea_supports',
      'Chip: "Protect clean air and water while keeping responsible jobs." Brownfield cleanup-and-reuse grants (1602, substitute only) are the clearest fit, alongside the conservation and preservation fund authorizations. Precedent: H.R. 7567 conservation programs on this key.',
      'https://www.congress.gov/119/crec/2026/11/10/172/169/modified/CREC-2026-11-10-pt1-PgS5471-2.htm', 'curated'),
    (m_s5653, 'tribal_consultation', 100, false, 'yea_supports',
      'Scope: government-to-government consultation, Tribal sovereignty, and protection of Tribal land, resources and cultural sites. Sec. 2212 lets a Tribe grant rights-of-way over its own land without Interior approval, Sec. 2301 writes a definition of property of traditional religious or cultural importance into law, and Sec. 2302 creates grants for Tribal Historic Preservation Officers. Split row: the sections that run against this key are in the yea_opposes row below. Contested: see claim tribal-consultation.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'tribal_consultation', 100, false, 'yea_opposes',
      'Sec. 2301 narrows what counts as an "adverse effect" (visual, atmospheric and audible elements generally excluded), which shrinks the set of effects on Tribal cultural sites that trigger review. It also adds 54 U.S.C. 302707, under which Interior must disapprove a Tribal preservation program, and suspend its contracts, if the Tribal Historic Preservation Officer does not regularly meet consultation timelines. Both cut against the key. The substitute adds that agencies keep their duty to consult Tribes under section 302706(b), which limits but does not remove these effects. Split row: the sections that run with this key are in the yea_supports row above. Contested: see claim tribal-consultation.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'property_rights', 100, false, 'yea_opposes',
      'Scope: what a government may do to a parcel its owner holds, including eminent domain and condemnation. Sec. 2101 directs FERC to issue construction permits for interstate lines it finds in the national interest, and a permit holder may acquire rights-of-way by eminent domain under existing Federal Power Act sec. 216(e). Sec. 2101(d) amends that condemnation subsection: actions follow federal Rule 71.1 rather than State-court practice, and the substitute removes the exclusion for State-owned land. More permits carrying the same taking power run against the key. Split row: the section that runs with this key is in the yea_supports row below.',
      'https://www.congress.gov/119/crec/2026/11/10/172/169/modified/CREC-2026-11-10-pt1-PgS5471-2.htm', 'curated'),
    (m_s5653, 'property_rights', 100, false, 'yea_supports',
      'Scope covers a government forbidding a use of a parcel. Sec. 2211 bars Interior from requiring a federal drilling permit for wells on non-Federal land where the federal share of the unit''s minerals is under 50 percent, leaving State and Tribal rules in place. That removes a federal condition on a use of non-federal land, which runs with the key. It is one section about a permit, not a taking. Split row: the sections that run against this key are in the yea_opposes row above.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'mine_cleanup', 100, false, 'yea_supports',
      'Scope: cleaning up abandoned mines and handling mining waste. Sec. 2215(d) creates a dedicated fund, paid by mill-site claim fees and hardrock lease receipts and spendable without further appropriation, only for the IIJA sec. 40704 abandoned hardrock mine reclamation program. New mandatory money for cleanup runs with the key. It is one subsection of Sec. 2215. Split row: the sections that run against this key are in the yea_opposes row below.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'mine_cleanup', 100, false, 'yea_opposes',
      'Scope covers where waste rock and tailings may go. Sec. 2215(a) defines a mill site as public land reasonably necessary for waste rock or tailings disposal and lets a claimant locate as many as are reasonably necessary, notwithstanding the existing limits in Revised Statutes sec. 2337(a) and (b). Each site is capped at 5 acres, but the number is not. Widening where mining waste may be placed on public land runs against the key. It is the operative body of the section. Split row: the subsection that runs with this key is in the yea_supports row above.',
      'https://www.govinfo.gov/content/pkg/BILLS-119s5653is/html/BILLS-119s5653is.htm', 'curated'),
    (m_s5653, 'gov_transparency', 100, false, 'yea_supports',
      'Scope includes publishing the basis for decisions. A public permitting tracker (1132), EIA data-center load reporting (2114), and a 72-hour DOE notice of nuclear safety-standard changes (2261) all require more disclosure. These are narrow links.',
      'https://www.congress.gov/119/crec/2026/11/10/172/169/modified/CREC-2026-11-10-pt1-PgS5471-2.htm', 'curated'),
    (m_s5653, 'disaster_resilience', 100, false, 'yea_supports',
      'Chip: "Prepare for wildfires." Sec. 1601 (substitute only) makes prescribed fire, including Tribal cultural burning, an exceptional event for air-quality data, easing fuel-reduction burns. It is one section.',
      'https://www.congress.gov/119/crec/2026/11/10/172/169/modified/CREC-2026-11-10-pt1-PgS5471-2.htm', 'curated')
  ON CONFLICT (measure_id, issue_key, support_meaning) DO NOTHING;

  -- ── sponsors ──────────────────────────────────────────────────────────────
     'https://www.congress.gov/bill/119th-congress/senate-bill/5653/cosponsors', 'Sen. Capito, Shelley Moore [R-WV]. Sponsor, joined 2026-09-30.'),
