  VALUES (m_s5653, 'senate', 119, 2, 257, TIMESTAMPTZ '2026-11-09T12:00:00-05:00', 'On Cloture on the Motion to Proceed H.R. 2347', 'cloture', 'Cloture on the Motion to Proceed Agreed to (73-25, 3/5 majority required)', '3/5',
    '{"yea":73,"nay":25,"present":0,"notVoting":2,"byParty":{"D":{"yea":21,"nay":23},"R":{"yea":51,"nay":1},"I":{"yea":1,"nay":1}}}'::jsonb, 'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1192/vote_119_2_00257.htm', 'U.S. Senate')
