  VALUES (m_s5653, 'senate', 119, 2, 258, TIMESTAMPTZ '2026-11-10T12:00:00-05:00', 'On the Motion to Proceed H.R. 2347', 'motion', 'Motion to Proceed Agreed to (62-21)', '1/2',
    '{"yea":62,"nay":21,"present":0,"notVoting":17,"byParty":{"D":{"yea":15,"nay":19},"R":{"yea":46,"nay":1},"I":{"yea":1,"nay":1}}}'::jsonb, 'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1192/vote_119_2_00258.htm', 'U.S. Senate')
