    '{"yea":70,"nay":26,"present":0,"notVoting":4,"byParty":{"D":{"yea":18,"nay":24},"R":{"yea":51,"nay":1},"I":{"yea":1,"nay":1}}}'::jsonb, 'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1192/vote_119_2_00266.htm', 'U.S. Senate')
