-- ── verification ────────────────────────────────────────────────────────────
DO $$
DECLARE m integer; n_iss integer; n_rc integer; n_mv integer;
BEGIN
  SELECT id INTO m FROM vr_measures WHERE congress = 119 AND chamber = 'senate' AND number = 'S. 5653' LIMIT 1;
  IF m IS NULL THEN RAISE EXCEPTION 'BAAJA: S. 5653 is not in vr_measures.'; END IF;
  SELECT count(*) INTO n_iss FROM vr_measure_issues WHERE measure_id = m;
  IF n_iss <> 18 THEN RAISE EXCEPTION 'BAAJA: expected 18 mapping rows, found %', n_iss; END IF;
  SELECT count(*) INTO n_rc FROM vr_rollcalls WHERE measure_id = m;
  IF n_rc <> 6 THEN RAISE EXCEPTION 'BAAJA: expected 6 roll calls, found %', n_rc; END IF;
  SELECT count(*) INTO n_mv FROM vr_member_votes v JOIN vr_rollcalls r ON r.id = v.rollcall_id WHERE r.measure_id = m;
  IF n_mv <> 600 THEN RAISE EXCEPTION 'BAAJA: member vote count is %', n_mv; END IF;
END $$;
